import{initNeighborBehavior,neighborBehaviorStep,neighborPurposeWeight,neighborMemory,rememberNeighborContact,validateNeighborBehavior}from './neighbor-behavior.js';
import{memoryBias}from './behavior.js';
import{mix}from './world.js';
export const SOCIAL_PURPOSES=['play','cautious','curious','food','reunion','territory','rest'];
export function initNeighbors(s){s.neighborhood??={version:1,animals:[],recent:[],counts:{}};const a=s.neighborhood.animals;for(let i=0;i<3;i++){const id=i===0?s.friend.id:`neighbor:${s.areaId}:${i}`;if(a.some(x=>x.id===id))continue;const code=mix(`${s.lifeId}:${id}`,1010);a.push({id,species:'dog',breed:['지역 믹스','소형 믹스','스피츠 타입 믹스'][code%3],name:i===0?s.friend.name:['흰 가슴의 작은 개','등이 짙은 개'][i-1],sex:code%2?'암컷':'수컷',coat:['밝은 털과 흰 발끝','갈색 털과 짙은 귀','검정·흰색 얼룩'][code%3],birthDay:s.day-(code%500),health:85,area:s.areaId,traits:{curiosity:20+code%70,caution:20+mix(code,1)%70,sociability:20+mix(code,2)%70,energy:20+mix(code,3)%70,independence:20+mix(code,4)%70,sensitivity:20+mix(code,5)%70,adaptability:20+mix(code,6)%70},bond:i===0?s.friend.bond:0,interactions:[],lastSeen:null,purpose:null,condition:'well',nextHealth:120+code%300});}for(const animal of a)initNeighborBehavior(s,animal);return s.neighborhood;}
export function neighborStep(s){const n=initNeighbors(s);for(const a of n.animals){if(a.alive===false)continue;a.alive??=true;a.age=s.day-a.birthDay;if(s.day>=a.nextHealth){a.nextHealth=s.day+180+mix(s.seed+s.day,a.birthDay)%180;if(a.condition==='well'&&a.age>365&&mix(a.id,s.day)%5===0){a.condition='resting';a.health=Math.max(45,a.health-10);a.recoverAt=s.day+14}else if(a.condition==='well')a.health=Math.max(45,a.health-(a.age>2920?2:0));}if(a.age>5475&&a.age>5475+mix(a.id,1020)%1500&&!a.declineAt){a.declineAt=s.day;a.condition='aging';}if(a.declineAt&&s.day-a.declineAt>=90){a.alive=false;a.condition='died';a.deathDay=s.day;a.cause='노년기 쇠약';}if(a.condition==='resting'&&s.day>=a.recoverAt){a.condition='well';a.health=Math.min(90,a.health+8)}neighborBehaviorStep(s,a)}if(s.day%365===0&&n.animals.filter(a=>a.area===s.areaId&&a.alive!==false).length<2){const template=n.animals.find(a=>a.area===s.areaId);if(template){const code=mix(s.seed+s.day,1030);n.animals.push({...template,id:`arrival:${s.areaId}:${s.day}`,name:'새로 지내기 시작한 개',birthDay:s.day-180-code%500,age:180+code%500,alive:true,condition:'well',health:85,bond:0,interactions:[],lastSeen:null,relationship:undefined,declineAt:null,deathDay:null,nextHealth:s.day+180,autonomy:undefined,traits:{...template.traits}});initNeighborBehavior(s,n.animals.at(-1));}}const focused=n.animals.find(a=>a.id===s.friend.id);if(!focused||focused.alive===false||focused.area!==s.areaId)selectNeighbor(s);}
function selectNeighbor(s){const n=initNeighbors(s),current=n.animals.find(a=>a.id===s.friend.id);if(current){current.relationship={...s.friend};current.bond=s.friend.bond;}const local=n.animals.filter(a=>a.area===s.areaId&&a.alive!==false);if(!current||current.area!==s.areaId||current.alive===false||s.friend.met&&s.friend.meetings>=3&&mix(s.seed+s.day,1009)%4===0){const choices=local.filter(a=>a.id!==s.friend.id);const next=choices.length?choices[mix(s.seed+s.day,1008)%choices.length]:null;if(next){s.friend=next.relationship?{...next.relationship}:{id:next.id,area:next.area,name:next.name,met:false,bond:next.bond,meetings:0,lastMet:null};s.dogBond=s.friend.bond;}}}
function focusActor(s){const n=initNeighbors(s);return n.animals.find(a=>a.id===s.friend.id)}
export function socialScene(s){selectNeighbor(s);let a=focusActor(s);const f=s.friend;if(!a||a.area!==s.areaId||a.alive===false){const next=initNeighbors(s).animals.find(x=>x.area===s.areaId&&x.alive!==false);if(next){s.oldFriends.push({...s.friend});s.friend={id:next.id,area:next.area,name:next.name,met:false,bond:next.bond,meetings:0,lastMet:null};return socialScene(s)}return {text:'이전에 함께 머물던 자리는 비어 있다. 오늘은 그 길을 지나 조용한 곳에서 쉰다.',options:[]};}const places={family:'사람과 산책줄을 매고 나온 공원 입구',shelter:'직원이 지켜보는 공동 운동장',street:'생활하던 골목의 쉼터'};const place=s.environmentModel?.facility==='petshop'?'직원이 지켜보는 판매점의 분리된 놀이 자리':places[s.home];const candidates=SOCIAL_PURPOSES.filter(p=>p!=='play'||s.day-a.birthDay>=26).filter(p=>p!=='territory'||s.day-a.birthDay>=180).filter(p=>!['play','territory'].includes(p)||(!s.clinical?.active&&a.health>=70&&a.condition!=='aging')).filter(p=>p!=='reunion'||f.met&&f.bond>=15).filter(p=>p!=='food'||s.home==='street'||s.home==='shelter').filter(p=>p!=='territory'||f.bond<40);if(a.health<70||a.age>2920){candidates.unshift('rest')}let pool=candidates.filter(p=>!s.neighborhood.recent.slice(-2).some(x=>x.actor===a.id&&x.purpose===p));if(!pool.length)pool=candidates;const weights=pool.map(p=>neighborPurposeWeight(s,a,p,p==='play'?.4+a.traits.energy/50:p==='cautious'?.3+a.traits.caution/40:p==='food'?.5+(100-s.worldModel.resource)/45:p==='reunion'?.4+f.bond/40:p==='rest'?.5+(100-a.health)/25:.8+a.traits.curiosity/90));let roll=mix(`${s.seed}:${s.day}:${a.id}`,f.meetings)/4294967296*weights.reduce((x,y)=>x+y,0),purpose=pool.at(-1);for(let i=0;i<pool.length;i++){roll-=weights[i];if(roll<=0){purpose=pool[i];break}}const scenes={
play:{opening:'앞다리를 낮추고 엉덩이를 높인 채 멈춘다. 두 걸음 다가왔다가 다시 뒤로 뛰며 빈 공간을 남긴다.',options:[['greet','몸을 낮추며 가벼운 놀이에 응한다','짧게 움직이며 서로 쫓고 멈추는 순서를 맞춘다.',8],['watch','뛰지 않고 옆에서 몸짓을 살핀다','상대가 멈추자 옆에 머문다. 뛰는 대신 같은 공간에서 쉬었다.',3],['retreat','움직임이 적은 쪽으로 거리를 벌린다','상대가 따라오지 않는다. 각자 편한 거리로 만남을 마친다.',0]]},
cautious:{opening:'몸을 낮추고 꼬리를 내린다. 내 움직임을 보다가 옆으로 한 걸음 비키며 몸을 굳힌다.',options:[['curve','정면 대신 큰 곡선을 그리며 비켜 간다','빈 공간이 넓어지자 상대의 몸에서 힘이 조금 풀렸다.',3],['still','고개를 돌린 채 잠시 멈춰 선다','시선을 떼고 기다리자 상대도 급하게 움직이지 않았다.',2],['retreat','뒤쫓지 않고 다른 쪽으로 돌아선다','서로를 압박하지 않고 만남을 끝냈다.',0]]},
curious:{opening:'몇 걸음 다가오다 옆으로 선다. 내 발걸음에 맞춰 움직이지만 갑자기 몸을 붙이지는 않는다.',options:[['greet','옆으로 다가가 짧게 코를 맞댄다','서로 잠깐 확인하고 다시 떨어졌다. 앞선 만남보다 덜 긴장한다.',6],['parallel','한 몸 길이 떨어져 같은 방향으로 걷는다','닿지 않는 거리를 두고 걸으니 발걸음이 차분해졌다.',5],['sniff','바닥을 살피며 상대가 지나가게 둔다','상대가 옆으로 지나간 뒤 원래 하던 일을 이어 간다.',1]]},
food:{opening:'먹이가 남은 자리 가까이 서 있다. 내가 움직이자 그릇 쪽으로 몸을 옮기고 발을 멈춘다.',options:[['separate','그릇과 떨어진 다른 자리로 간다','같은 먹이 앞에 몰리지 않았다. 서로 떨어진 곳에서 움직인다.',2],['wait','상대가 자리를 비울 때까지 멀리 머문다','조금 기다린 뒤 빈 공간을 살폈다. 가까이 밀어붙이지 않았다.',1],['leave','오늘은 그 자리를 두고 돌아선다','먹이 자리를 두고 맞서지 않고 생활하던 쪽으로 돌아갔다.',0]]},
reunion:{opening:'나를 보자 몸의 힘을 풀고 익숙하게 다가온다. 지난번 함께 쉬었던 쪽으로 머리를 돌린다.',options:[['greet','짧게 인사한 뒤 곁에서 함께 걷는다','서로의 보폭에 맞춰 움직인다. 전에 함께 머문 자리에 다시 쉬었다.',9],['rest','익숙한 그늘에 먼저 몸을 눕힌다','친구도 조금 떨어져 눕는다. 가만히 쉬어도 곁이 편하다.',6],['space','오늘은 짧게 인사하고 내 길을 간다','오래 놀지 않고 각자의 활동으로 돌아갔다. 만남의 익숙함은 남는다.',3]]},
territory:{opening:'좁은 통로 앞에 멈춰 서서 몸을 세운다. 지금은 그 사이를 곧장 지나가기 어렵다.',options:[['detour','넓은 옆길로 돌아간다','몸을 맞댈 만큼 가까워지지 않고 넓은 쪽으로 통과했다.',1],['wait','통로에서 떨어져 상대가 움직이기를 기다린다','상대가 자리를 옮긴 뒤 비어 있는 통로를 지났다.',1],['retreat','막힌 길 대신 원래 자리로 돌아간다','길을 양보하고 익숙한 쪽으로 돌아왔다. 더 몰아붙이지 않았다.',0]]},
rest:{opening:'평소보다 느리게 움직이다 그늘에 눕는다. 다가오는 움직임을 보고도 바로 일어나지 않는다.',options:[['quiet','떨어진 옆자리에 누워 함께 쉰다','움직임을 재촉하지 않고 조용히 같은 그늘에서 시간을 보냈다.',4],['pass','몸을 붙이지 않고 천천히 지나간다','쉬는 자리를 비워 주고 내 길을 이어 갔다.',1],['watch','한동안 떨어져 상태를 살핀다','상대가 쉬는 모습을 보다 다른 쪽으로 움직였다.',2]]}};const spec=scenes[purpose],signature=`${a.id}:${purpose}:${s.areaId}:${spec.options.map(o=>o[0]).join(',')}`;a.purpose=purpose;a.lastSeen=s.day;s.friend.sex=a.sex;s.friend.breed=a.breed;s.currentEncounter={actorId:a.id,purpose,signature,options:spec.options,place,day:s.day};s.neighborhood.recent.push({actor:a.id,purpose,day:s.day,signature});s.neighborhood.recent=s.neighborhood.recent.slice(-12);s.neighborhood.counts[purpose]=(s.neighborhood.counts[purpose]||0)+1;return {text:`${place}에서 ${a.coat}의 ${a.name}와 마주쳤다. ${spec.opening}`,options:spec.options.map(o=>o.slice(0,2))};}
export function resolveSocialScene(s,id,log,remember,clamp){const e=s.currentEncounter;if(!e||e.actorId!==s.friend.id||e.day!==s.day)return false;const actor=focusActor(s);if(!actor||actor.alive===false||actor.area!==s.areaId)return false;const o=e.options.find(o=>o[0]===id);if(!o)return false;const a=focusActor(s),f=s.friend,stress=e.purpose==='territory'||e.purpose==='food'?2:-2;f.met=true;f.meetings++;f.lastMet=s.day;const threshold=a.traits.sociability+(id==='greet'?15:30)+f.bond/5+memoryBias(s,a.id)+neighborMemory(a,s.lifeId,s.day)*.4-s.stress/5-a.autonomy.needs.stress*.15;const positive=mix(s.seed+s.day,f.meetings+1100)%100<threshold;f.bond=clamp(f.bond+o[3]+(positive?0:-2));s.dogBond=f.bond;s.stress=clamp(s.stress+stress);a.bond=f.bond;rememberNeighborContact(s,a,id,positive);a.interactions.push({day:s.day,purpose:e.purpose,action:id,result:positive?'settled':'distance'});a.interactions=a.interactions.slice(-20);a.lastSeen=s.day;log(s,'dog-friend',`${a.name}와 ${f.meetings}번째 만남. ${o[2]}${positive?'':' 잠시 뒤 상대가 거리를 벌려 오늘은 짧게 마쳤다.'}`);Object.assign(s.log.at(-1),{actorId:a.id,purpose:e.purpose,signature:e.signature,storyId:`social:${a.id}`});remember(s,positive?'dog-positive-contact':'dog-space');s.currentEncounter=null;return true;}
export function validateNeighbors(s){if(s.neighborhood&&(!Array.isArray(s.neighborhood.animals)||!s.neighborhood.animals.every(a=>typeof a.id==='string'&&typeof a.area==='string'&&Number.isFinite(a.health)&&a.traits&&Array.isArray(a.interactions))))throw Error('손상된 주변 동물 기록');for(const a of s.neighborhood?.animals||[])validateNeighborBehavior(a,s.day);}
